package app

func sandboxAgentTools() []builtinToolDefinition {
	return []builtinToolDefinition{
		{"read", "读取文件", "Read numbered UTF-8 lines. offset is a 1-based line number (default 1), limit defaults to 2000. Use the last displayed line + 1 to continue. Paths are relative to the session CWD or absolute under /data.", "read_only", `{"type":"object","properties":{"file_path":{"type":"string","minLength":1,"maxLength":1024},"offset":{"type":"integer","minimum":1,"maximum":100000000},"limit":{"type":"integer","minimum":1,"maximum":2000}},"required":["file_path"],"additionalProperties":false}`},
		{"read_image", "读取图片", "Read a PNG, JPEG or WebP file as native model vision input when the session model supports images. Large images are automatically scaled for model input. This reads a private snapshot into model history; use save_artifacts to explicitly retain a deliverable. Paths are relative to CWD or absolute under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024}},"required":["path"],"additionalProperties":false}`},
		{"write", "写入文件", "Create or fully replace a UTF-8 text file in an existing directory. Returns the applied diff. Up to 32768 input bytes and 65536 existing file bytes.", "side_effect", `{"type":"object","properties":{"file_path":{"type":"string","minLength":1,"maxLength":1024},"content":{"type":"string","maxLength":32768}},"required":["file_path","content"],"additionalProperties":false}`},
		{"edit", "编辑文件", "Replace literal UTF-8 text. The match must be unique unless replace_all is true. Supports files up to 65536 bytes and returns the applied diff.", "side_effect", `{"type":"object","properties":{"file_path":{"type":"string","minLength":1,"maxLength":1024},"old_string":{"type":"string","minLength":1,"maxLength":8192},"new_string":{"type":"string","maxLength":16384},"replace_all":{"type":"boolean"}},"required":["file_path","old_string","new_string"],"additionalProperties":false}`},
		{"glob", "查找文件", "Find regular files, newest first, using a slash-aware glob pattern below a directory. Searches are bounded and exclude private platform state; link handling follows the filesystem provider. Paths are relative to CWD or under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","maxLength":1024},"pattern":{"type":"string","minLength":1,"maxLength":1024},"limit":{"type":"integer","minimum":1,"maximum":200}},"required":["pattern"],"additionalProperties":false}`},
		{"grep", "搜索文件内容", "Find text in UTF-8 files below a directory and return numbered matches grouped by file. Use include to filter candidate files by a single provider glob. The pattern is a case-sensitive Go regular expression by default. Use literal=true for plain text or case_sensitive=false to ignore case. Searches skip private platform state and files larger than the 8 MiB scan budget; link handling follows the filesystem provider. Paths are relative to CWD or under /data.", "read_only", `{"type":"object","properties":{"path":{"type":"string","maxLength":1024},"pattern":{"type":"string","minLength":1,"maxLength":1024},"include":{"type":"string","minLength":1,"maxLength":1024},"literal":{"type":"boolean"},"case_sensitive":{"type":"boolean"},"limit":{"type":"integer","minimum":1,"maximum":250}},"required":["pattern"],"additionalProperties":false}`},
		{"load_artifacts", "载入制品", "Copy saved artifacts from this session into the working directory. Destination defaults to the saved filename. Existing files are never overwritten.", "side_effect", `{"type":"object","properties":{"items":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","properties":{"artifact_id":{"type":"string","pattern":"^[1-9][0-9]*$"},"destination":{"type":"string","minLength":1,"maxLength":1024}},"required":["artifact_id"],"additionalProperties":false}}},"required":["items"],"additionalProperties":false}`},
		{"exec_command", "执行命令", "Run a shell command as the default workspace user in this session CWD. Commands share files, dependencies and ports with other sessions. Use background=true for longer work, then process_status/output/cancel. Returned execution_id is a platform ID, not a PID. Secrets and external-service authorization are not granted by shell access.", "side_effect", `{"type":"object","properties":{"command":{"type":"string","minLength":1,"maxLength":32768},"background":{"type":"boolean"},"timeout_seconds":{"type":"integer","minimum":1,"maximum":600},"max_output_bytes":{"type":"integer","minimum":4,"maximum":65536}},"required":["command"],"additionalProperties":false}`},
		{"process_status", "查询进程", "Inspect a command execution from this root run. Only a verified exit is completion; outcome_unknown must be reconciled before repeating side effects.", "read_only", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"}},"required":["execution_id"],"additionalProperties":false}`},
		{"process_output", "读取进程输出", "Read bounded output from a command in this root run. Pass the returned cursor to continue; background output may merge stdout and stderr.", "read_only", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"},"cursor":{"type":"string","maxLength":4096},"max_output_bytes":{"type":"integer","minimum":4,"maximum":65536}},"required":["execution_id"],"additionalProperties":false}`},
		{"process_cancel", "取消进程", "Request cancellation of a command in this root run. A cancellation acknowledgement does not by itself prove the process has stopped; inspect the returned state.", "side_effect", `{"type":"object","properties":{"execution_id":{"type":"string","pattern":"^[1-9][0-9]*$"}},"required":["execution_id"],"additionalProperties":false}`},
		{"save_artifacts", "保存制品", "Save snapshots of files in this working directory by relative or absolute path. Returns artifact IDs for later use. Up to 20 files, 100 MiB each and 200 MiB total.", "side_effect", `{"type":"object","properties":{"files":{"type":"array","minItems":1,"maxItems":20,"items":{"type":"object","properties":{"path":{"type":"string","minLength":1,"maxLength":1024},"description":{"type":"string","maxLength":2000}},"required":["path"],"additionalProperties":false}}},"required":["files"],"additionalProperties":false}`},
	}
}

func isSandboxAgentTool(key string) bool {
	for _, definition := range sandboxAgentTools() {
		if definition.key == key {
			return true
		}
	}
	return false
}
